\begin{QuestionSolution}{2024 年第 4 题}
\textbf{入手角度}\quad 检查变换能否把两个不同的常数映成同一个值，再找可连续反解的变换。

\textbf{解析}\quad 令 \(a_n\) 在 \(2\) 和 \(\frac{1}{2}\) 间交替，\(a_n+\frac{1}{a_n}\) 恒为 \(\frac{5}{2}\)，排除 A。令 \(a_n=(-1)^n\)，\(a_n-\frac{1}{a_n}\) 恒为零，且 \(\mathrm{e}^{a_n}+\mathrm{e}^{-a_n}\) 恒为 \(\mathrm{e}+\mathrm{e}^{-1}\)，排除 B、C。若 \(b_n=\mathrm{e}^{a_n}-\mathrm{e}^{-a_n}\) 收敛，解二次方程得
\[
a_n=\ln\frac{b_n+\sqrt{b_n^2+4}}2.
\]
右端是 \(b_n\) 的连续函数，故 \(a_n\) 也收敛，与已知矛盾。选 D。
\end{QuestionSolution}

% Q 2012 10
\QuestionPage{1.2 数列的极限}{填空题}{2012 年第 10 题}{2}{和式型数列极限与夹逼准则}{007 / 234}
计算$\lim_{n \to \infty} n\left(\frac{1}{1 + n^2} + \frac{1}{2^2 + n^2}
+ \cdots + \frac{1}{n^2 + n^2} \right) =$ \blank{}．
\QuestionEnd

\begin{QuestionSolution}{2012 年第 10 题}
\textbf{入手角度}\quad 每个分母提出 \(n^2\)，各项便对应等分区间 \([0,1]\) 的右端点。

\textbf{解析}\quad 将原式写为
\[
n\sum_{k=1}^n\frac{1}{n^2+k^2}
=\frac1n\sum_{k=1}^n\frac{1}{1+(\frac{k}{n})^2}.
\]
被积函数 \(t\mapsto(1+t^2)^{-1}\) 在 \([0,1]\) 上连续。当 \(n\to\infty\) 时，右端的 Riemann 和趋于 \(\int_0^1(1+t^2)^{-1}\,\mathrm{d}t=[\arctan t]_0^1=\boxed{\frac{\pi}{4}}\)。
\end{QuestionSolution}

% Q 2011 19
\QuestionPage{1.2 数列的极限}{解答题}{2011 年第 19 题}{3}{调和和式与数列收敛}{008 / 234}
\begin{enumerate}
\item
证明：对任意的正整数$n$，都有$\frac{1}{n + 1} < \ln \left(1 + \frac{1}{n} \right) < \frac{1}{n}$成立．
\item
设$a_n = 1 + \frac{1}{2} + \cdots + \frac{1}{n} - \ln n$（$n = 1,2, \cdots$），
证明数列$\left\{a_n \right\}$收敛．
\end{enumerate}
\QuestionEnd

\begin{QuestionSolution}{2011 年第 19 题}
\textbf{入手角度}\quad 对数增量可写为 \(\frac{1}{t}\) 在单位区间上的积分，上下界能同时用于判断单调性和给出下界。

\textbf{解析}\quad （1）在 \(n<t<n+1\) 上有 \(\frac{1}{n+1}<\frac{1}{t}<\frac{1}{n}\)，积分即得
\[
\frac1{n+1}<\int_n^{n+1}\frac{\mathrm{d}t}{t}
=\ln(1+\frac{1}{n})<\frac1n.
\]
（2）由左侧不等式，\(a_{n+1}-a_n=\frac{1}{n+1}-\ln(1+\frac{1}{n})<0\)。对右侧不等式从 \(k=1\) 加到 \(k=n-1\) 得
\(\ln n\le\sum_{k=1}^{n-1}\frac{1}{k}\)，其中 \(n=1\) 时两边为零。因此 \(a_n\ge \frac{1}{n}>0\)。数列单调递减且有下界，故收敛。
\end{QuestionSolution}

% Q 2012 21
\QuestionPage{1.2 数列的极限}{解答题}{2012 年第 21 题}{4}{实根构成的数列极限}{009 / 234}
\begin{enumerate}
\item
证明方程$x^n + x^{n - 1} + \cdots + x = 1$（$n$为大于$1$的整数）
在区间$\left(\frac{1}{2},1 \right)$内有且仅有一个实根；
\item
记第（1）问中的实根为$x_n$，证明$\lim_{n \to \infty} x_n$存在，并求此极限．
\end{enumerate}
\QuestionEnd

\begin{QuestionSolution}{2012 年第 21 题}
\textbf{入手角度}\quad 增加一项会使固定正数处的多项式变大，利用这一点比较相邻的根，再对有限等比和求极限。

\textbf{解析}\quad （1）记 \(P_n(t)=\sum_{k=1}^n t^k\)。它在 \([\frac{1}{2},1]\) 连续且严格递增，\(P_n(\frac{1}{2})=1-2^{-n}<1<P_n(1)=n\)，所以恰有一根 \(x_n\in(\frac{1}{2},1)\) 使 \(P_n(x_n)=1\)。

（2）\(P_{n+1}(x_n)=1+x_n^{n+1}>1=P_{n+1}(x_{n+1})\)，故 \(x_{n+1}<x_n\)，从而 \(x_n\) 收敛且 \(x_n\le x_2<1\)。等比求和得 \(2x_n-1=x_n^{n+1}\)，而右端介于零与 \(x_2^{n+1}\) 之间，趋于零。故 \(\lim_{n\to\infty}x_n=\boxed{\frac{1}{2}}\)。
\end{QuestionSolution}

% Q 2013 20
\QuestionPage{1.2 数列的极限}{解答题}{2013 年第 20 题}{3}{不等式约束下的数列极限}{010 / 234}
设函数$f(x) = \ln x + \frac{1}{x}$．
\begin{enumerate}
\item
求$f(x)$的最小值；
\item
设数列$\{x_n\}$满足$\ln x_n + \frac{1}{x_{n + 1}} < 1$，证明$\lim_{n \to \infty} x_n$存在，并求此极限．
\end{enumerate}
\QuestionEnd

\begin{QuestionSolution}{2013 年第 20 题}
\textbf{入手角度}\quad 先求同一个自变量下的下界，再将它与题给的相邻两项不等式相减。

\textbf{解析}\quad （1）定义域为 \(x>0\)，且 \(f'(x)=\frac{x-1}{x^2}\)，故 \(f\) 在 \((0,1)\) 递减，在 \((1,\infty)\) 递增，最小值为 \(f(1)=1\)。

（2）题意给出每个 \(x_n>0\)。由
\[
\ln x_n+\frac1{x_{n+1}}<1\le\ln x_n+\frac1{x_n}
\]
可知 \(x_{n+1}>x_n\)。左侧原不等式还给出 \(\ln x_n<1\)，故 \(x_n<\mathrm{e}\)。由单调有界准则，\(x_n\to L\ge x_1>0\)。取极限得 \(f(L)\le1\)，而（1）表明只有 \(L=1\) 时 \(f(L)\le1\)。所求极限为 \(\boxed{1}\)。
\end{QuestionSolution}

% Q 2018 21
\QuestionPage{1.2 数列的极限}{解答题}{2018 年第 21 题}{4}{递推数列的收敛与极限}{011 / 234}
设数列$\left\{x_n \right\}$满足：$x_1 > 0$，$x_n \mathrm{e}^{x_{n + 1}} = \mathrm{e}^{x_n} - 1$（$n = 1,2, \cdots$）．
证明$\left\{x_n \right\}$收敛，并求$\lim_{n \to \infty} x_n$．
\QuestionEnd

\begin{QuestionSolution}{2018 年第 21 题}
\textbf{入手角度}\quad 把 \(\frac{\mathrm{e}^x-1}{x}\) 写成 \(\mathrm{e}^t\) 在 \([0,x]\) 上的平均值，可直接比较递推的相邻项。

\textbf{解析}\quad 当 \(x_n>0\) 时，
\[
1<\mathrm{e}^{x_{n+1}}=\frac1{x_n}\int_0^{x_n}\mathrm{e}^t\,\mathrm{d}t<\mathrm{e}^{x_n}.
\]
故 \(0<x_{n+1}<x_n\)，由 \(x_1>0\) 归纳得数列递减且有下界。设 \(x_n\to L\ge0\)。若 \(L>0\)，递推式取极限给出 \(\mathrm{e}^L=\frac{\mathrm{e}^L-1}{L}\)，但同一平均值严格小于 \(\mathrm{e}^L\)，矛盾。所以 \(\lim_{n\to\infty}x_n=\boxed{0}\)。
\end{QuestionSolution}

